// Some portions generated by Claude
export type MissingEdgeQueryBatch = {
  sourceIds: string[];
  targetIds: string[];
  query: string;
};

type MissingEdgeBatchOptions = {
  sourceBatchSize: number;
  targetBatchSize: number;
};

const SAFE_SPARQL_IRI =
  /^[A-Za-z][A-Za-z0-9+.-]*:[^<>"{}|^`\\\s]+$/;

function chunkItems<T>(items: T[], size: number) {
  const chunks: T[][] = [];
  for (let index = 0; index < items.length; index += size) {
    chunks.push(items.slice(index, index + size));
  }
  return chunks;
}

function valuesClause(values: string[]) {
  return values.map((value) => `<${value}>`).join(" ");
}

export function buildMissingEdgeQueryBatches(
  nodeIds: string[],
  options: MissingEdgeBatchOptions,
): MissingEdgeQueryBatch[] {
  const ids = [...new Set(nodeIds)].filter((nodeId) =>
    SAFE_SPARQL_IRI.test(nodeId),
  );
  if (ids.length < 2) return [];

  const normalizeBatchSize = (value: number) =>
    Number.isFinite(value) && value > 0
      ? Math.max(1, Math.floor(value))
      : ids.length;
  const sourceBatchSize = normalizeBatchSize(options.sourceBatchSize);
  const targetBatchSize = normalizeBatchSize(options.targetBatchSize);
  const sourceBatches = chunkItems(ids, sourceBatchSize);
  const targetBatches = chunkItems(ids, targetBatchSize);

  return sourceBatches.flatMap((sourceIds) =>
    targetBatches.map((targetIds) => ({
      sourceIds,
      targetIds,
      query: `SELECT DISTINCT ?source ?predicate ?target WHERE {
  VALUES ?source { ${valuesClause(sourceIds)} }
  VALUES ?target { ${valuesClause(targetIds)} }
  ?source ?predicate ?target .
  FILTER(?source != ?target)
}`,
    })),
  );
}
